import java.util.Scanner;

public class Main {
    static long total_input, max_depth, current_value, base_num, answer = Long.MAX_VALUE, boundary;
    static long[] array = new long[500000];

    static void explore(long x, long s, long base, long depth) {
        if (s >= total_input) return;
        if (x == 0) {
            System.out.println(s);
            System.exit(0);
        }
        while (base > x) {
            base /= 10;
            depth--;
        }
        explore(0, s + ((base * 10 + 1) - x) + depth + 1, base * 10 + 1, depth + 1);
        long q = x / base;
        explore((base * 10 + 1) - x, s + depth + 1, base, depth);
        explore(x - (base * q), s + (depth * q), base, depth);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        total_input = sc.nextLong();
        base_num = 1;
        boundary = 1;
        while (base_num * 10 + 1 <= total_input) {
            base_num = base_num * 10 + 1;
            boundary++;
        }
        for (int i = 0; i < total_input; i++) {
            explore(total_input, 0, base_num, boundary);
        }
        if (answer == Long.MAX_VALUE) {
            answer = Math.min(total_input, 11 - total_input + 2);
        }
        System.out.println(answer);
        sc.close();
    }
}
